			text = [=[Разелих Осквернитель — повелитель ужаса {link:burning-legion}Пылающего Легиона{/link} и подлинный хозяин Выжженных земель. Когда-то он был самым страшным помощником владыки {link:lord-kazzak}Каззак{/link}а. Теперь он правит пустошами из логова на вершине самой высокой горы этой земли, и ему служат {link:ogres}огр{/link}ы и сектанты этого края.]=],
		},
		{
			title = "Значение",
			text = [=[Когда Легион был побежден, а {link:lord-kazzak}Каззак{/link} отошел в {link:the-tainted-scar}Гниющий шрам{/link}, Разелих был послан закрепить за ним эту землю. Он сделал это больше хитростью, чем силой. Пока {link:alliance}Альянс{/link} и {link:horde}Орда{/link} ссорились из-за земель далеко на севере, он собрал воедино разрозненные секты {link:shadow-council}Совета Теней{/link} и {link:ogres}огр{/link}ов Молота Ужаса. Ценой, которую он предложил, была сила. Он сделал амулет, разломил его натрое и дал по куску верховному магу {link:archmage-allistarj}Аллистарж{/link}у, леди Севине и огру {link:grol-the-destroyer}Грол{/link}у Разрушителю. Каждый кусок делал своего носителя бессмертным в пределах Выжженных земель. Каждый также привязывал носителя к вечной службе демону. Трое его капитанов поняли второй дар лишь тогда, когда было уже поздно.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он закрепил {link:blasted-lands}Выжженные земли{/link} за владыкой {link:lord-kazzak}Каззак{/link}ом после поражения Легиона.
• Он объединил сектантов Присягнувших Тени и {link:ogres}огр{/link}ов Молота Ужаса под своим началом.
• Он захватил полк Орды и сделал души его солдат бессмертными рабами.
• Он привязал к себе трех капитанов кусками своего амулета.]=],
		},
	},
	chapters = {
		{
			title = "Полк",
			hint = "Выслушайте рассказ павшего героя Орды на краю болота.",
			text = [=[Призрак у границы болота был некогда командиром Орды Требором. Он повел полк в пустоши, и слуги Осквернителя взяли его в плен. Разелих вырвал души из пленных солдат и привязал их тела к камням. Девятерых он оставил себе и привязал возле Темного портала. Остальных девятерых он разделил между своими капитанами, по трое каждому. Без душ эти бойцы не могут умереть. Именно их пленение, сказал охотник на демонов {link:loramus-thalipedes}Лорамус{/link}, скрепило договор между демоном, сектантами и {link:ogres}огр{/link}ами.]=],
		},
		{
			title = "Камни уз",
			hint = "Освободите связанных солдат погибшего полка.",
			text = [=[{link:kirith-the-damned}Кирит{/link} нашел слабое место прежде, чем сгинул сам. Каждого связанного солдата можно было избить до грани распада, и лишь в этот миг его камень уз можно было разбить. Восемнадцать камней были разбиты по всем Выжженным землям — возле Портала и в логовах трех капитанов. Солдаты полка были наконец отпущены на покой. Разелих лишился своей бессмертной стражи и узнал, что на него кто-то охотится.]=],
		},
		{
			title = "Расколотый амулет",
			hint = "Сокрушите троицу и соберите амулет воедино.",
			text = [=[{link:neeka-bloodscar}Ника{/link}кой обычный клинок не мог ранить трех капитанов. Охотник на демонов {link:loramus-thalipedes}Лорамус Талипедес{/link} знал истинное имя Осквернителя и вместе с кузнецом {link:galvan-the-ancient}Галван{/link}ом Древним помог выковать из азшарита оружие, несущее это имя. Этим оружием были повержены {link:grol-the-destroyer}Грол{/link}, {link:lady-sevine}Севина{/link} и {link:archmage-allistarj}Аллистарж{/link}, и три их куска амулета вновь соединились. Осквернитель почувствовал, что его цепь повелений разорвана. Он понял, что на него охотятся.]=],
		},
		{
			title = "Ты — Рак'лих",
			hint = "Используйте амулет у Алтаря Осквернителя.",
			text = [=[Амулет открыл путь на вершину. У Алтаря Осквернителя демон был вызван. Он призвал своих слуг — хранителя душ Илифара и своего защитника Фелкулара — и бился на краю горы. Он пал. Один из его рогов унесли с горы как доказательство того, что демонического владыку Выжженных земель можно победить. Оберег, который он выковал, отдали призраку Требора на уничтожение, чтобы никто не мог воспользоваться им вновь.]=],
		},
	},
	mentions = {
		{
			text = [=[«Мелкие дрязги», путь {link:alliance}Альянс{/link}а к павшему герою]=],
		},
		{ text = "«Утрата милости», путь Орды к павшему герою" },
		{ text = "«Под покровом тьмы», тайна троицы" },
		{ text = "«Охотник на демонов»" },
		{ text = "«Возвращение в {link:blasted-lands}Выжженные земли{/link}»" },
	},
	bonds = {
		{ id = "lord-kazzak", name = "владыка Каззак", note = "его хозяин" },
		{ id = "grol-the-destroyer", name = "Грол Разрушитель", note = "связанный капитан" },
		{ id = "archmage-allistarj", name = "верховный маг Аллистарж", note = "связанный капитан" },
		{ id = "lady-sevine", name = "леди Севина", note = "связанный капитан" },
		{ id = "fallen-hero-of-the-horde", name = "Павший герой Орды", note = "его пленник и его враг" },
		{ id = "loramus-thalipedes", name = "Лорамус Талипедес", note = "знает его истинное имя" },
	},
})

