	aliases = { "Лангерц" },
	sections = {
		{
			title = "Обзор",
			text = [=[Интендант Лангерц ведает складами Крепости Стражей Пустоты. Он — нить, связывающая крепость с королевствами. Еда, оружие, камни силы и реагенты, нужные ее магам, — все должно приходить по длинной дороге из {link:stormwind-city}Штормград{/link}а, и за все это отвечает он. Слишком многое не доходит. {link:ogres}Огры{/link} нападают на обозы в болоте, и повозки пропадают между {link:darkshire}Темнолесьем{/link} и крепостью. Каждую доставку он встречает как маленькое чудо, и порой это и есть чудо.]=],
		},
	},
	chapters = {
		{
			title = "Дорога в крепость",
			hint = "Доставьте припасы по длинной дороге в крепость.",
			text = [=[Камни силы из Темнолесья, которые потеряли бы заряд, если бы ждали следующего обоза. Бочонок с клеймом его имени, найденный далеко от дороги. Последний ящик, спасенный из разбитого обоза, который вел дозорный {link:watcher-biggs}Биггс{/link} и который крепость уже считала потерянным вместе с возницей. Каждая вещь попала к нему из рук путника, и каждая рассказывала одно и то же. В крепости недостает всего, и прежде всего — азорских кристаллов, без которых ее маги не могут обойтись.]=],
