Translate("ruRU", "thadius-grimshade", {
	title = "Тадиус Мрачная Тень",
	subtitle = "Прорицатель Крепости Стражей Пустоты",
	found = "Башня магов Крепости Стражей Пустоты",
	hint = [=[Ищите прорицателя из клана Неистового Молота в башне крепости.]=],
