	chapters = {
		{
			title = "Прорицание",
			hint = "Принесите прорицателю перо грифона и уплатите его цену.",
			text = [=[Повелители грифонов Заоблачного Пика прислали ему перо из гнезда молодого грифона Остроклюва, которого украли. Мрачная Тень сперва назвал цену: медальон тролля Некрума Кишкожуя из {red:zul-farrak}Зул'Фаррака{/red}, даровавший своему владельцу неестественно долгую жизнь. Он надеялся узнать его тайну, избежав его проклятия. Когда медальон оказался у него, он совершил прорицание, прошел по нити от пера к грифону и нашел, что Остроклюв сидит в плену в городе троллей во {link:the-hinterlands}Внутренних землях{/link}.]=],
