Translate("ruRU", "kum-isha-the-collector", {
	title = "Кум'иша Собиратель",
	subtitle = "Искатель кристаллов дренетиста",
	found = "В пустошах близ Утеса Осквернителя",
	hint = [=[Ищите изгнанника, который собирает кристаллы в сердце пустошей.]=],
	allegiance = "Заблудшие дренеи",
	aliases = { "Кум'иша" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кум'иша Собиратель — один из заблудших дренеев, которые бродят по Выжженным землям, изгнанник древнего народа из мира по ту сторону {link:dark-portal}Темного портала{/link}. Он держит лагерь в сердце пустошей и собирает дренетист — кристалл своей родины, который до сих пор можно найти в красной земле. Он верит, что, набрав его достаточно, сумеет открыть разлом и увести свой народ домой.]=],
		},
		{
			title = "Значение",
			text = [=[Кум'иша озлоблен, горд и остер на язык. {link:humans}Люди{/link} и {link:orcs}орк{/link}и жалуются на вонь друг друга, замечает он, но для его носа все народы этого мира пахнут одинаково, и чует он в них алчность. Алчность стоила ему дома, говорит он, и алчность оплатит его возвращение. Он охотно меняет свои сокровища на кристаллы у тех, кто их приносит, и презирает их за то, что они идут на этот обмен.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он обыскивает {link:blasted-lands}Выжженные земли{/link} ради кристаллов дренетиста, и прежде всего — ради редких безупречных сфер.
• Он пытался открыть разлом на свою родину.
• Он платит за каждый принесенный ему осколок кристалла и презирает тех, кто их приносит.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, как Кум'иша и его спутники попали в {link:blasted-lands}Выжженные земли{/link} и как долго они там скитаются.]=],
		},
	},
	chapters = {
		{
			title = "Безупречная сфера",
			hint = "Принесите собирателю самый редкий кристалл пустошей.",
			text = [=[Дренеи тратили целую жизнь на поиски одной-единственной безупречной сферы дренетиста, сказал Кум'иша, и умирали, не закончив поисков. Когда такую сферу положили ему в руки, он не мог поверить. Он тотчас попытался сотворить портал домой. Попытка не удалась. Надежды он не потерял. Он попросил еще одну сферу.]=],
		},
		{
			title = "Хлам одного дренея",
			hint = "Принесите собирателю меньшие осколки кристалла.",
			text = [=[Осколки дренетиста с изъяном никогда не откроют пути домой. Но Кум'иша берет и их, ибо они могут послужить его народу иначе, и платит за них сокровищами этого мира, которые называет хламом. Одни и те же презрительные слова он говорит каждому продавцу помногу раз в день. Он признает, что ненавидит этот мир.]=],
		},
	},
	mentions = {
		{ text = "«Служить Кум'ише»" },
		{ text = "«Старания Кум'иши»" },
		{ text = "«В больших количествах важно все»" },
		{ text = "«Хлам одного дренея...»" },
	},
})

